import sys
import types

NS = types.SimpleNamespace
TICKETS = [{"id": 1042, "text": "Charged twice for order 1042"},
           {"id": 1043, "text": "Can't reset my password"},
           {"id": 1044, "text": "Invoice shows the wrong VAT number"}]
BATCH_ID = "msgbatch_01HkcTjaV5uDC8jWR4ZsDV8d"


def prompt_for(ticket):
    return f"Label this ticket with one category from the taxonomy:\n{ticket['text']}"


def _text_message(text):
    return NS(content=[NS(type="thinking", thinking="", signature="Eos..."),
                       NS(type="text", text=text)], stop_reason="end_turn")


class _AsyncMessages:
    async def create(self, *, model, max_tokens, messages, **kwargs):
        return _text_message("billing")


class _Batches:
    def create(self, *, requests):
        ids = [r["custom_id"] for r in requests]
        assert len(ids) == len(set(ids)) and len(ids) <= 100_000
        return NS(id=BATCH_ID, processing_status="in_progress")

    def results(self, batch_id):
        def err(kind):
            return NS(type="errored", error=NS(type="error", error=NS(type=kind)))
        return iter([
            NS(custom_id="ticket-1044", result=NS(type="succeeded",
               message=_text_message("billing"))),
            NS(custom_id="ticket-1042", result=NS(type="succeeded",
               message=_text_message("billing"))),
            NS(custom_id="ticket-1043", result=err("api_error")),
        ])


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(batches=_Batches())


class _AsyncAnthropic:
    def __init__(self, **kwargs):
        self.messages = _AsyncMessages()


sys.modules["anthropic"] = NS(Anthropic=_Anthropic, AsyncAnthropic=_AsyncAnthropic)
client = _Anthropic()
